/**
 * reset_leave_data.js
 * 
 * Safely resets all leave-related data in the BIT Non-Teaching Staff Portal database:
 * 1. Clears all leave applications (leaves collection).
 * 2. Resets all user leave balances (used = 0, reserved = 0) while preserving annual entitlements.
 * 3. Removes attendance records specifically generated by approved leaves (status: 'Leave' / 'On-Leave').
 * 4. Resets leaveDays in payroll records without deleting payroll history.
 * 5. Cleans up leave-related notification activity logs.
 * 6. Preserves all accounts, credentials, departments, schedules, salaries, and non-leave attendance.
 */

require('dotenv').config({ path: `${__dirname}/../.env` });
const mongoose = require('mongoose');
const Leave = require('../models/Leave.model');
const User = require('../models/User.model');
const Attendance = require('../models/Attendance.model');
const Department = require('../models/Department.model');
const Payroll = require('../models/Payroll.model');
const Schedule = require('../models/Schedule.model');
const Notification = require('../models/Notification.model');

const MONGODB_URI = process.env.MONGODB_URI;

const resetLeaveData = async () => {
  console.log('🔗 Connecting to MongoDB...');
  await mongoose.connect(MONGODB_URI);
  console.log('✅ Connected to MongoDB\n');

  try {
    // ── 1. AUDIT BEFORE RESET ───────────────────────────────────────────
    console.log('====================================================');
    console.log('        AUDIT BEFORE LEAVE DATA RESET              ');
    console.log('====================================================');
    
    const preLeavesCount = await Leave.countDocuments();
    const preLeaveAttendanceCount = await Attendance.countDocuments({ status: { $in: ['Leave', 'On-Leave'] } });
    const preNonLeaveAttendanceCount = await Attendance.countDocuments({ status: { $nin: ['Leave', 'On-Leave'] } });
    const preTotalAttendanceCount = await Attendance.countDocuments();
    const preTotalUsers = await User.countDocuments();
    const preTotalDepartments = await Department.countDocuments();
    const preTotalPayrolls = await Payroll.countDocuments();
    const prePayrollsWithLeaves = await Payroll.countDocuments({ leaveDays: { $gt: 0 } });
    const preLeaveNotifications = await Notification.countDocuments({
      $or: [{ title: /Leave/i }, { message: /leave/i }],
    });

    console.log(`- Leave applications in DB:             ${preLeavesCount}`);
    console.log(`- Leave attendance records to clear:    ${preLeaveAttendanceCount}`);
    console.log(`- Valid non-leave attendance to keep:   ${preNonLeaveAttendanceCount}`);
    console.log(`- Total attendance records:             ${preTotalAttendanceCount}`);
    console.log(`- Users in system:                      ${preTotalUsers}`);
    console.log(`- Departments in system:                ${preTotalDepartments}`);
    console.log(`- Payroll records in system:            ${preTotalPayrolls}`);
    console.log(`- Payroll records with leaveDays > 0:   ${prePayrollsWithLeaves}`);
    console.log(`- Leave-related notifications:          ${preLeaveNotifications}`);
    console.log('====================================================\n');

    // ── 2. EXECUTE RESET ────────────────────────────────────────────────
    console.log('--- Executing Leave Data Reset ---');

    // Step A: Clear all Leave applications
    const leaveDeleteResult = await Leave.deleteMany({});
    console.log(`✅ [1/5] Cleared all leave applications: ${leaveDeleteResult.deletedCount} records deleted.`);

    // Step B: Reset leave balances for all users (used = 0, reserved = 0)
    // We update every user while keeping their default/configured annual allowance intact
    const allUsers = await User.find({});
    let usersResetCount = 0;

    for (const u of allUsers) {
      if (!u.leaveBalances) {
        u.leaveBalances = {
          casualLeave: { total: 12, used: 0, reserved: 0 },
          medicalLeave: { total: 12, used: 0, reserved: 0 },
          earnedLeave: { total: 12, used: 0, reserved: 0 },
        };
      } else {
        const clTotal = u.leaveBalances.casualLeave?.total ?? 12;
        const mlTotal = u.leaveBalances.medicalLeave?.total ?? 12;
        const elTotal = u.leaveBalances.earnedLeave?.total ?? 12;

        u.leaveBalances.casualLeave = { total: clTotal, used: 0, reserved: 0 };
        u.leaveBalances.medicalLeave = { total: mlTotal, used: 0, reserved: 0 };
        u.leaveBalances.earnedLeave = { total: elTotal, used: 0, reserved: 0 };
      }
      u.markModified('leaveBalances');
      await u.save();
      usersResetCount++;
    }
    console.log(`✅ [2/5] Reset leave balances to 0 used/reserved for all ${usersResetCount} users.`);

    // Step C: Delete attendance records created by approved leaves
    const attDeleteResult = await Attendance.deleteMany({ status: { $in: ['Leave', 'On-Leave'] } });
    console.log(`✅ [3/5] Removed generated leave attendance records: ${attDeleteResult.deletedCount} records removed.`);

    // Step D: Reset leaveDays in payroll records to 0
    const payrollUpdateResult = await Payroll.updateMany(
      { leaveDays: { $gt: 0 } },
      { $set: { leaveDays: 0, excessLeaveDays: 0 } }
    );
    console.log(`✅ [4/5] Reset leaveDays in payroll records: ${payrollUpdateResult.modifiedCount} records updated.`);

    // Step E: Clean up leave-related notifications
    const notifDeleteResult = await Notification.deleteMany({
      $or: [{ title: /Leave/i }, { message: /leave/i }],
    });
    console.log(`✅ [5/5] Cleaned up leave-related activity notifications: ${notifDeleteResult.deletedCount} notifications removed.\n`);

    // ── 3. AUDIT AFTER RESET ────────────────────────────────────────────
    console.log('====================================================');
    console.log('        AUDIT AFTER LEAVE DATA RESET               ');
    console.log('====================================================');

    const postLeavesCount = await Leave.countDocuments();
    const postPendingLeaves = await Leave.countDocuments({ status: 'Pending' });
    const postApprovedLeaves = await Leave.countDocuments({ status: 'Approved' });
    const postRejectedLeaves = await Leave.countDocuments({ status: 'Rejected' });
    const postCancelledLeaves = await Leave.countDocuments({ status: 'Cancelled' });
    const postLeaveAttendanceCount = await Attendance.countDocuments({ status: { $in: ['Leave', 'On-Leave'] } });
    const postNonLeaveAttendanceCount = await Attendance.countDocuments({ status: { $nin: ['Leave', 'On-Leave'] } });
    const postTotalUsers = await User.countDocuments();
    const postTotalDepartments = await Department.countDocuments();
    const postTotalPayrolls = await Payroll.countDocuments();
    const postPayrollsWithLeaves = await Payroll.countDocuments({ leaveDays: { $gt: 0 } });
    const postUsersWithUsedLeaves = await User.countDocuments({
      $or: [
        { 'leaveBalances.casualLeave.used': { $gt: 0 } },
        { 'leaveBalances.casualLeave.reserved': { $gt: 0 } },
        { 'leaveBalances.medicalLeave.used': { $gt: 0 } },
        { 'leaveBalances.medicalLeave.reserved': { $gt: 0 } },
        { 'leaveBalances.earnedLeave.used': { $gt: 0 } },
        { 'leaveBalances.earnedLeave.reserved': { $gt: 0 } },
      ],
    });

    console.log(`- Total leave applications:             ${postLeavesCount}  (EXPECTED: 0)`);
    console.log(`- Pending leaves:                       ${postPendingLeaves}  (EXPECTED: 0)`);
    console.log(`- Approved leaves:                      ${postApprovedLeaves}  (EXPECTED: 0)`);
    console.log(`- Rejected leaves:                      ${postRejectedLeaves}  (EXPECTED: 0)`);
    console.log(`- Cancelled leaves:                     ${postCancelledLeaves}  (EXPECTED: 0)`);
    console.log(`- Leave attendance records:             ${postLeaveAttendanceCount}  (EXPECTED: 0)`);
    console.log(`- Users with non-zero used balances:    ${postUsersWithUsedLeaves}  (EXPECTED: 0)`);
    console.log(`- Payrolls with leaveDays > 0:          ${postPayrollsWithLeaves}  (EXPECTED: 0)`);
    console.log('----------------------------------------------------');
    console.log(`- PRESERVED Valid non-leave attendance: ${postNonLeaveAttendanceCount}`);
    console.log(`- PRESERVED Users:                      ${postTotalUsers}`);
    console.log(`- PRESERVED Departments:                ${postTotalDepartments}`);
    console.log(`- PRESERVED Payroll records:            ${postTotalPayrolls}`);
    console.log('====================================================\n');

    const allZero =
      postLeavesCount === 0 &&
      postPendingLeaves === 0 &&
      postApprovedLeaves === 0 &&
      postRejectedLeaves === 0 &&
      postCancelledLeaves === 0 &&
      postLeaveAttendanceCount === 0 &&
      postUsersWithUsedLeaves === 0 &&
      postPayrollsWithLeaves === 0;

    const dataPreserved =
      postTotalUsers === preTotalUsers &&
      postTotalDepartments === preTotalDepartments &&
      postTotalPayrolls === preTotalPayrolls &&
      postNonLeaveAttendanceCount === preNonLeaveAttendanceCount;

    if (allZero && dataPreserved) {
      console.log('🎉 SUCCESS: All leave-related data successfully reset to zero.');
      console.log('🎉 SUCCESS: All user accounts, departments, payroll history, and attendance records preserved.');
    } else {
      console.error('⚠️ WARNING: Post-reset validation did not meet all expected conditions.');
      process.exit(1);
    }
  } catch (err) {
    console.error('❌ Error during leave data reset:', err);
    process.exit(1);
  } finally {
    await mongoose.disconnect();
    console.log('🔌 Disconnected from MongoDB');
  }
};

resetLeaveData();
